"""Builds syllabus labs A (regression types), B (activation functions), C (ML vs MAP), E (Q-learning)."""
import nbformat as nbf
C = lambda t: nbf.v4.new_code_cell(t); M = lambda t: nbf.v4.new_markdown_cell(t)
S = "import sys; sys.path.insert(0, '../../src')\nimport numpy as np, pandas as pd, matplotlib.pyplot as plt\nnp.set_printoptions(precision=3, suppress=True); pd.set_option('display.width', 160)"
def save(cells, name):
    nb = nbf.v4.new_notebook(); nb.cells = cells; nbf.write(nb, f"notebooks/syllabus/{name}.ipynb")

# ---------- A regression types
save([
M("# Lab A - Types of regression\nSimple, multiple, polynomial, ridge/lasso (regularized), and logistic regression (regression used for classification). Data: California Housing (target = median house value in $100k)."),
C(S + "\nfrom arena.data import load_california, load_titanic\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.linear_model import LinearRegression, Ridge, Lasso, LogisticRegression\nfrom sklearn.preprocessing import PolynomialFeatures, StandardScaler\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.metrics import mean_squared_error, r2_score\nX, y = load_california(); X, _, y, _ = train_test_split(X, y, train_size=4000, random_state=0)\nXtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.25, random_state=0)\nrmse = lambda m, A, b: np.sqrt(mean_squared_error(b, m.predict(A)))"),
M("## 1. Simple linear regression (one feature: MedInc) vs. 2. Multiple linear regression (all 8 features)"),
C("simple = LinearRegression().fit(Xtr[['MedInc']], ytr); multi = LinearRegression().fit(Xtr, ytr)\npd.DataFrame({'simple (MedInc)': [rmse(simple, Xtr[['MedInc']], ytr), rmse(simple, Xte[['MedInc']], yte), r2_score(yte, simple.predict(Xte[['MedInc']]))],\n              'multiple (8 features)': [rmse(multi, Xtr, ytr), rmse(multi, Xte, yte), r2_score(yte, multi.predict(Xte))]}, index=['train RMSE', 'test RMSE', 'test R2']).round(3)"),
M("## 3. Polynomial regression: degree sweep on MedInc, trained on only 30 rows (under- vs over-fitting)"),
C("Xs, ys = Xtr.iloc[:30], ytr.iloc[:30]   # tiny training set makes overfitting visible\nrows = []\nfor d in [1, 2, 3, 4, 5, 6, 8]:\n    m = make_pipeline(PolynomialFeatures(d), StandardScaler(), LinearRegression()).fit(Xs[['MedInc']], ys)\n    rows.append((d, rmse(m, Xs[['MedInc']], ys), rmse(m, Xte[['MedInc']], yte)))\nr = pd.DataFrame(rows, columns=['degree', 'train_rmse', 'test_rmse']).set_index('degree'); display(r.round(3)); r.plot(marker='o', figsize=(6, 3.5), logy=True); plt.ylabel('RMSE (log scale)'); plt.show()"),
M("With 30 training rows, train RMSE keeps falling as the degree rises, while test RMSE explodes: the polynomial passes through the training points but oscillates elsewhere. That gap is **overfitting**; degree 1-2 underfits/fits sensibly. (With all 4000 rows the curve stays flat because MedInc alone is a weak predictor.)"),
M("## 4. Regularized regression: Ridge (L2) and Lasso (L1) shrink coefficients"),
C("sc = StandardScaler().fit(Xtr); A, B = sc.transform(Xtr), sc.transform(Xte)\ncoefs = pd.DataFrame({'OLS': LinearRegression().fit(A, ytr).coef_, 'Ridge a=100': Ridge(100).fit(A, ytr).coef_, 'Lasso a=0.05': Lasso(0.05).fit(A, ytr).coef_}, index=X.columns).round(3); display(coefs)\nprint('Lasso zeroed features:', list(coefs.index[coefs['Lasso a=0.05'] == 0]))"),
M("## 5. Logistic regression: regression for classification (Titanic survival)\n`P(y=1|x) = 1 / (1 + exp(-(w.x+b)))`: linear model in the log-odds."),
C("from arena.evaluate import split\nfrom arena.preprocess import build_preprocessor\nfrom sklearn.metrics import accuracy_score\nacc = []\nfor s in range(5):\n    a, b, c, d = split('clf', s); pre, _ = build_preprocessor(a); m = LogisticRegression(max_iter=1000).fit(pre.fit_transform(a), c); acc.append(accuracy_score(d, m.predict(pre.transform(b))))\nprint('logistic regression accuracy over 5 seeds: %.3f +- %.3f' % (np.mean(acc), np.std(acc, ddof=1)))"),
M("## When to use which\n| Type | Use when | Risk |\n|---|---|---|\n| Simple linear | one dominant predictor, interpretability | ignores other features |\n| Multiple linear | several roughly linear effects | multicollinearity, non-linearity |\n| Polynomial | curved relationship in few features | overfitting at high degree |\n| Ridge / Lasso | many/correlated features, need shrinkage / feature selection | needs alpha tuning |\n| Logistic | binary target, want probabilities | linear decision boundary |"),
], "lab_a_regression_types")

# ---------- B activation functions
save([
M("# Lab B - Activation functions\nAn activation adds non-linearity so stacked layers can learn more than a linear map."),
C(S + "\nz = np.linspace(-6, 6, 400)\nf = {'sigmoid': 1/(1+np.exp(-z)), 'tanh': np.tanh(z), 'ReLU': np.maximum(0, z), 'Leaky ReLU (0.1)': np.where(z > 0, z, 0.1*z), 'identity': z}\nsig = f['sigmoid']; d = {'sigmoid': sig*(1-sig), 'tanh': 1-np.tanh(z)**2, 'ReLU': (z > 0).astype(float), 'Leaky ReLU (0.1)': np.where(z > 0, 1, 0.1), 'identity': np.ones_like(z)}\nfig, ax = plt.subplots(1, 2, figsize=(11, 3.8))\nfor k in f: ax[0].plot(z, f[k], label=k); ax[1].plot(z, d[k], label=k)\nax[0].set_title('activation'); ax[1].set_title('derivative'); ax[0].set_ylim(-2, 4); ax[1].set_ylim(-0.1, 1.3); ax[0].legend(fontsize=7); plt.show()"),
M("**Vanishing gradients:** sigmoid's derivative is at most 0.25 and ~0 for |z|>4; multiplying many such factors in backprop shrinks the gradient. **ReLU** has derivative 1 for z>0 (cheap, no saturation) but can 'die' (derivative 0 for z<0); Leaky ReLU keeps a small slope. **Identity** makes the whole network linear."),
C("print('max sigmoid derivative:', d['sigmoid'].max().round(3), '| max tanh derivative:', d['tanh'].max().round(3))"),
M("## Effect on a real network: MLP on Titanic, same architecture, only the activation changes (5 seeds)"),
C("from sklearn.neural_network import MLPClassifier\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import accuracy_score, f1_score\nfrom arena.evaluate import split\nfrom arena.preprocess import build_preprocessor\nimport warnings; warnings.filterwarnings('ignore')\nrows = []\nfor s in range(5):\n    a, b, c, e = split('clf', s); pre, _ = build_preprocessor(a); Za = pre.fit_transform(a); Zb = pre.transform(b)\n    for es in (True, False):\n        for act in ['identity', 'logistic', 'tanh', 'relu']:\n            m = MLPClassifier((32,), activation=act, alpha=1e-4, max_iter=1000, early_stopping=es, random_state=s).fit(Za, c); p = m.predict(Zb)\n            rows.append(dict(early_stopping=es, activation=act, seed=s, epochs=m.n_iter_, accuracy=accuracy_score(e, p), f1_macro=f1_score(e, p, average='macro')))\n    p = LogisticRegression(max_iter=1000).fit(Za, c).predict(Zb); rows.append(dict(early_stopping='-', activation='(logreg ref)', seed=s, epochs=np.nan, accuracy=accuracy_score(e, p), f1_macro=f1_score(e, p, average='macro')))\nr = pd.DataFrame(rows).groupby(['early_stopping', 'activation'])[['epochs', 'accuracy', 'f1_macro']].agg(['mean', 'std']).round(3); r"),
M("**Reading it.** With early stopping, the sigmoid (logistic) network stops after only ~20 epochs and underfits badly (much lower accuracy, large std): its small gradients make learning slow, so the validation score plateaus and training is cut off. Without early stopping (up to 1000 epochs) all four activations reach about the same accuracy (~0.83, equal to the logistic-regression reference within one std), but sigmoid/tanh/ReLU need many more epochs than identity. Take-away: activations differ mostly in **how fast and how reliably they train**; on this small, nearly linear problem they end up equally accurate. (An identity-activation MLP is just a linear model.)"),
], "lab_b_activation_functions")

# ---------- C ML vs MAP
save([
M("# Lab C - Maximum Likelihood (ML) vs. Maximum A Posteriori (MAP) hypotheses\n- **h_ML = argmax_h P(D | h)**: best explains the data.\n- **h_MAP = argmax_h P(D | h) P(h)**: also uses a prior. Equal when the prior is uniform."),
C(S + "\nfrom scipy.stats import beta"),
M("## 1. Classic example: a lab test\nP(disease)=0.008. Test: P(+|disease)=0.98, P(+|no disease)=0.03. A patient tests positive."),
C("prior = {'disease': 0.008, 'no disease': 0.992}; lik = {'disease': 0.98, 'no disease': 0.03}\npost_unnorm = {h: lik[h]*prior[h] for h in prior}; Z = sum(post_unnorm.values())\nprint(pd.DataFrame({'prior P(h)': prior, 'likelihood P(+|h)': lik, 'P(+|h)P(h)': post_unnorm, 'posterior P(h|+)': {h: v/Z for h, v in post_unnorm.items()}}).round(4))\nprint('h_ML =', max(lik, key=lik.get), '| h_MAP =', max(post_unnorm, key=post_unnorm.get))"),
M("The likelihood alone says *disease*, but the prior is so small that the most probable hypothesis is still *no disease* (posterior of disease ~ 0.21)."),
M("## 2. Coin toss: MLE vs. MAP with a Beta prior\nData: k heads in n tosses. MLE = k/n. With a Beta(a,b) prior the MAP estimate is (k+a-1)/(n+a+b-2)."),
C("def mle(k, n): return k / n\ndef map_est(k, n, a, b): return (k + a - 1) / (n + a + b - 2)\nrows = []\nfor k, n in [(3, 3), (7, 10), (70, 100), (700, 1000)]:\n    rows.append(dict(data=f'{k}/{n}', MLE=mle(k, n), **{f'MAP Beta({a},{b})': map_est(k, n, a, b) for a, b in [(1, 1), (5, 5), (20, 20)]}))\npd.DataFrame(rows).set_index('data').round(3)"),
M("Beta(1,1) is uniform, so MAP = MLE. A strong 'fair coin' prior Beta(20,20) pulls 3/3 heads far from 1.0, but with 1000 tosses the data dominates and all estimates agree."),
C("p = np.linspace(0, 1, 400); fig, ax = plt.subplots(1, 2, figsize=(11, 3.5))\nfor a_, b_ in [(1, 1), (5, 5), (20, 20)]: ax[0].plot(p, beta.pdf(p, a_ + 7, b_ + 3), label=f'posterior, prior Beta({a_},{b_})')\nax[0].axvline(0.7, color='k', ls=':', label='MLE 0.7'); ax[0].set_title('7 heads / 10 tosses'); ax[0].legend(fontsize=7)\nfor a_, b_ in [(1, 1), (5, 5), (20, 20)]: ax[1].plot(p, beta.pdf(p, a_ + 700, b_ + 300), label=f'prior Beta({a_},{b_})')\nax[1].set_title('700 heads / 1000 tosses'); ax[1].legend(fontsize=7); plt.show()"),
M("## 3. Discrete hypothesis space: which coin bias? (h in {0.3, 0.5, 0.8}); data: 7 heads, 3 tails"),
C("from scipy.stats import binom\nH = np.array([0.3, 0.5, 0.8]); L = binom.pmf(7, 10, H)\nfor name, pr in [('uniform prior', np.array([1/3, 1/3, 1/3])), ('prior favouring fair coin', np.array([0.1, 0.8, 0.1]))]:\n    post = L * pr / (L * pr).sum()\n    print(f'{name:28s} likelihood {L.round(3)} posterior {post.round(3)} -> h_ML={H[L.argmax()]}  h_MAP={H[post.argmax()]}')"),
M("## 4. Link to regression: Ridge regression is MAP with a Gaussian prior on the weights\nMinimizing `||y - Xw||^2 + alpha ||w||^2` equals MAP when w ~ N(0, sigma^2/alpha). Few data points -> prior matters, coefficients shrink toward 0."),
C("from sklearn.linear_model import LinearRegression, Ridge\nrng = np.random.default_rng(0); X = rng.normal(size=(8, 5)); w_true = np.array([2., -1., 0., 0., 1.]); y = X @ w_true + rng.normal(0, 1, 8)\nprint(pd.DataFrame({'true': w_true, 'OLS (=ML)': LinearRegression(fit_intercept=False).fit(X, y).coef_, 'Ridge alpha=5 (=MAP)': Ridge(5, fit_intercept=False).fit(X, y).coef_}).round(3))"),
], "lab_c_ml_vs_map")

# ---------- E Q-learning
save([
M("# Lab E - Q-learning (reinforcement learning)\nAn agent learns action values `Q(s,a)` by trial and error. Update rule:\n\n`Q(s,a) <- Q(s,a) + alpha * [ r + gamma * max_a' Q(s',a') - Q(s,a) ]`\n\nEnvironment: 4x4 gridworld, start top-left, goal bottom-right (+1), two pits (-1), small step cost (-0.01). Deterministic moves; hitting a wall leaves you in place."),
C(S + "\nN = 4; START, GOAL, PITS = (0, 0), (3, 3), {(1, 1), (2, 3)}; ACTIONS = ['up', 'down', 'left', 'right']; MOVES = [(-1, 0), (1, 0), (0, -1), (0, 1)]\ndef step(s, a):\n    r, c = s; dr, dc = MOVES[a]; n = (min(max(r + dr, 0), N - 1), min(max(c + dc, 0), N - 1))\n    if n == GOAL: return n, 1.0, True\n    if n in PITS: return n, -1.0, True\n    return n, -0.01, False\n\nalpha, gamma, episodes = 0.1, 0.95, 3000\nrng = np.random.default_rng(0); Q = np.zeros((N, N, 4)); returns = []\nfor ep in range(episodes):\n    eps = max(0.05, 1 - ep / (0.6 * episodes)); s, done, G = START, False, 0\n    for t in range(100):\n        a = rng.integers(4) if rng.random() < eps else int(np.argmax(Q[s]))\n        n, r, done = step(s, a)\n        Q[s][a] += alpha * (r + gamma * (0 if done else Q[n].max()) - Q[s][a])   # the Q-learning update\n        s, G = n, G + r\n        if done: break\n    returns.append(G)\nprint('trained for', episodes, 'episodes')"),
M("## Learning curve (average return per 100 episodes)"),
C("avg = np.array(returns).reshape(-1, 100).mean(axis=1); plt.figure(figsize=(6, 3.5)); plt.plot(np.arange(len(avg)) * 100, avg, marker='o'); plt.xlabel('episode'); plt.ylabel('mean return'); plt.show()\nprint('mean return first 100 episodes: %.2f, last 100: %.2f' % (np.mean(returns[:100]), np.mean(returns[-100:])))"),
M("## Learned greedy policy (arrows) and state values"),
C("arrow = ['^', 'v', '<', '>']; grid = [[('G' if (r, c) == GOAL else 'X' if (r, c) in PITS else arrow[int(np.argmax(Q[r, c]))]) for c in range(N)] for r in range(N)]\nprint('\\n'.join(' '.join(row) for row in grid)); print(); print('V(s) = max_a Q(s,a):'); print(Q.max(axis=2).round(2))"),
M("## One Q-update worked by hand\nTake state (3,2) and action 'right' (into the goal at (3,3)): r=+1, terminal so the future term is 0. From Q=0: new Q = 0 + 0.1*(1 + 0 - 0) = 0.1. Check with code:"),
C("Qh = np.zeros((N, N, 4)); s = (3, 2); a = 3; n, r, done = step(s, a)\nnew = Qh[s][a] + alpha * (r + gamma * (0 if done else Qh[n].max()) - Qh[s][a])\nprint(f'state {s}, action {ACTIONS[a]}, next {n}, reward {r}, terminal {done} -> Q_new = 0 + {alpha}*({r} + 0 - 0) = {new}')"),
M("**Exploration vs. exploitation:** epsilon-greedy picks a random action with probability epsilon (decayed from 1 to 0.05) so the agent first explores, then exploits what it learned. **Off-policy:** the update uses max over next actions, not the action actually taken."),
], "lab_e_q_learning")
